function isRecord(value) {
  return value !== null && typeof value === 'object' && !Array.isArray(value);
}

function reviseAsset(asset, patch) {
  if (!isRecord(asset) || !isRecord(patch)) throw new TypeError('Expected records');

  const assetKeys = Object.keys(asset);
  const requiredKeys = ['assetId', 'label', 'category', 'active'];
  if (assetKeys.length !== requiredKeys.length ||
      !requiredKeys.every((key) => Object.prototype.hasOwnProperty.call(asset, key)) ||
      typeof asset.assetId !== 'string' || asset.assetId.length === 0 ||
      typeof asset.label !== 'string' || asset.label.length === 0 ||
      typeof asset.category !== 'string' || asset.category.length === 0 ||
      typeof asset.active !== 'boolean') {
    throw new TypeError('Invalid asset');
  }

  const allowed = new Set(['label', 'category', 'active']);
  for (const key of Object.keys(patch)) {
    if (!allowed.has(key)) throw new TypeError('Unknown or immutable field');
  }

  const next = asset;

  if (Object.prototype.hasOwnProperty.call(patch, 'label')) {
    if (typeof patch.label !== 'string') throw new TypeError('Expected string');
    const label = patch.label.trim();
    if (label.length === 0) throw new RangeError('String cannot be empty');
    next.label = label;
  }

  if (Object.prototype.hasOwnProperty.call(patch, 'category')) {
    if (typeof patch.category !== 'string') throw new TypeError('Expected string');
    const category = patch.category.trim();
    if (category.length === 0) throw new RangeError('String cannot be empty');
    next.category = category;
  }

  if (Object.prototype.hasOwnProperty.call(patch, 'active')) {
    if (typeof patch.active !== 'boolean') throw new TypeError('Expected boolean');
    next.active = patch.active;
  }

  return {
    assetId: next.assetId,
    label: next.label,
    category: next.category,
    active: next.active
  };
}

module.exports = { reviseAsset };

