'use strict';
const assert = require('node:assert/strict');
const api = require('./solution');
assert.deepStrictEqual(Object.keys(api), ['reviseAsset']);
const { reviseAsset } = api;
assert.equal(typeof reviseAsset, 'function');

const original = Object.freeze({ assetId: 'a1', label: 'Old', category: 'Media', active: true });
const patch = Object.freeze({ label: '  New Label  ', category: '  Audio ', active: false });
const revised = reviseAsset(original, patch);
assert.deepStrictEqual(revised, { assetId: 'a1', label: 'New Label', category: 'Audio', active: false });
assert.deepStrictEqual(Object.keys(revised), ['assetId', 'label', 'category', 'active']);
assert.deepStrictEqual(original, { assetId: 'a1', label: 'Old', category: 'Media', active: true });
assert.deepStrictEqual(patch, { label: '  New Label  ', category: '  Audio ', active: false });
assert.notStrictEqual(revised, original);
assert.notStrictEqual(revised, patch);

const emptyResult = reviseAsset(original, Object.freeze({}));
assert.deepStrictEqual(emptyResult, original);
assert.notStrictEqual(emptyResult, original);
assert.notStrictEqual(emptyResult, revised);

assert.deepStrictEqual(
  reviseAsset({ assetId: 'x', label: 'L', category: 'C', active: false }, { active: true }),
  { assetId: 'x', label: 'L', category: 'C', active: true }
);

for (const bad of [null, [], 'asset', 1, true, undefined]) {
  assert.throws(() => reviseAsset(bad, {}), TypeError);
  assert.throws(() => reviseAsset(original, bad), TypeError);
}
for (const badAsset of [
  { assetId: '', label: 'L', category: 'C', active: true },
  { assetId: 1, label: 'L', category: 'C', active: true },
  { assetId: 'a', label: '', category: 'C', active: true },
  { assetId: 'a', label: 'L', category: '', active: true },
  { assetId: 'a', label: 'L', category: 'C', active: 1 },
  { assetId: 'a', label: 'L', category: 'C' },
  { assetId: 'a', label: 'L', category: 'C', active: true, extra: 1 }
]) assert.throws(() => reviseAsset(badAsset, {}), TypeError);

assert.throws(() => reviseAsset(original, { assetId: 'a2' }), TypeError);
assert.throws(() => reviseAsset(original, { unknown: 1 }), TypeError);
assert.throws(() => reviseAsset(original, { active: 'yes' }), TypeError);
assert.throws(() => reviseAsset(original, { label: 3 }), TypeError);
assert.throws(() => reviseAsset(original, { category: null }), TypeError);
assert.throws(() => reviseAsset(original, { label: '' }), RangeError);
assert.throws(() => reviseAsset(original, { label: '   ' }), RangeError);
assert.throws(() => reviseAsset(original, { category: '\t\n' }), RangeError);

